  function storyFeedCard(story,index=0){const liked=(state.storyLikes[story.id]||[]).includes(state.currentUserId),saved=state.savedStories.some(x=>x.storyId===story.id&&x.userId===state.currentUserId);return `<article id="story-${escapeHtml(story.id)}" class="panel feed-story"><div class="feed-story-author">${avatar(getUser(story.userId),'avatar-s')}<div><b>${escapeHtml(getUser(story.userId).name)}</b><small>⌖ ${escapeHtml(story.destination)} · ${dateFmt((story.createdAt||'').slice(0,10))}</small></div><span class="feed-public">PUBLIC</span></div><h2>${escapeHtml(story.title)}</h2><p class="feed-story-text">${escapeHtml(story.body)}</p><img class="feed-story-image" src="${escapeHtml(storyImage(story,index))}" alt="Travel photo from ${escapeHtml(story.destination)}" loading="lazy"><div class="feed-actions"><button class="${liked?'feed-action active':''}" data-story-like="${story.id}" aria-label="Like story">${liked?'♥':'♡'} <span>${(state.storyLikes[story.id]||[]).length}</span></button><a class="feed-action" href="#places" data-story-destination="${escapeHtml(story.destination)}">⌖ <span>Explore</span></a><button class="feed-action ${saved?'active':''}" data-story-save="${story.id}" aria-label="Save story">${saved?'▣':'♧'} <span>${saved?'Saved':'Save'}</span></button><button class="feed-action" data-nav="stories">↗ <span>Share</span></button></div></article>`;}
  function renderHome(){const trips=myTrips(),upcoming=trips.filter(t=>t.endDate>=today()).sort((a,b)=>a.startDate.localeCompare(b.startDate)),nearest=upcoming[0],stories=[...(state.stories||[])].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return `<section class="page-heading feed-heading"><div><div class="eyebrow">YOUR TRAVEL COMMUNITY</div><h1>Travel stories from your circle.</h1><p>Discover a place, share a tip, and plan the next journey together.</p></div><div class="heading-actions"><button class="btn btn-primary" data-action="share-story">＋ Create post</button></div></section><section class="social-home"><div class="feed-main"><div class="panel feed-composer"><div class="feed-composer-top">${avatar(currentUser(),'avatar-s')}<button data-action="share-story">Share a travel tip or a moment from your journey…</button></div><div class="feed-composer-actions"><button data-action="share-story">▧ Add photos</button><button data-action="share-story">⌖ Add a place</button><button class="btn btn-primary btn-sm" data-action="share-story">Create post</button></div></div>${stories.length?stories.map((s,i)=>storyFeedCard(s,i)).join(''):`<article class="panel empty-state"><b>Your travel feed starts here</b><p>Share your first destination tip or trip photo.</p><button class="btn btn-primary btn-sm" data-action="share-story">Create post</button></article>`}</div><aside class="feed-right">${nearest?`<article class="panel upcoming-widget"><div class="panel-head"><div><div class="panel-title">Your upcoming trip</div><div class="panel-sub">Your next shared adventure</div></div><button class="text-link" data-nav="trips">View all</button></div><div class="upcoming-image" style="background-image:url('https://images.unsplash.com/photo-1599661046827-dacff0c0f09a?auto=format&fit=crop&w=700&q=80')"></div><b>${escapeHtml(nearest.title)}</b><small>${escapeHtml(nearest.destination)} · ${dateRange(nearest)}</small><button class="btn btn-primary btn-sm" data-open-trip="${nearest.id}">Open trip →</button></article>`:`<article class="panel upcoming-widget"><div class="panel-title">Your upcoming trip</div><div class="feed-empty-pin">⌖</div><b>No trip planned yet</b><p>Your next adventure appears here after you plan it.</p><button class="btn btn-primary btn-sm" data-action="new-trip">Create trip</button></article>`}<article class="feed-ai-card"><div class="eyebrow">TRIP COMPANION</div><h3>Need a travel idea?</h3><p>Search a destination or explore the place guide to plan your next visit.</p><button class="btn btn-light btn-sm" data-nav="places">Explore places →</button></article><article class="panel trending-widget"><div class="panel-title">Trending destinations</div>${[['Goa','photo-1512343879784-a960bf40e7f2'],['Jaipur','photo-1599661046827-dacff0c0f09a'],['Kerala','photo-1602216056096-3b40cc0c9944']].map(([name,img])=>`<button data-featured-place="${name}"><img src="https://images.unsplash.com/${img}?auto=format&fit=crop&w=160&q=70" alt=""><span><b>#${name}</b><small>Explore destination</small></span></button>`).join('')}</article></aside></section>`;}
  const toursAvailable=()=>state.trips.filter(t=>t.visibility==='public'&&!members(t.id).some(m=>m.userId===state.currentUserId)&&!(t.status==='completed'));
  function renderTours(){const trips=toursAvailable().filter(t=>!tourQuery||`${t.title} ${t.destination} ${t.interests} ${getUser(t.ownerId).name} ${getUser(t.ownerId).city}`.toLowerCase().includes(tourQuery.toLowerCase()));return `<section class="page-heading"><div><div class="eyebrow">TRAVEL WITH GOOD COMPANY</div><h1>Find a tour to join.</h1><p>Discover shared plans, find people with similar interests, and request a spot.</p></div><div class="heading-actions"><button class="btn btn-primary" data-action="new-trip"><span class="icon-add">＋</span> Post a tour</button></div></section><div class="filter-row"><label class="search-box"><span>⌕</span><input id="tourSearch" value="${escapeHtml(tourQuery)}" placeholder="Search a destination or interest…"></label><select id="tourSort" class="select-small"><option value="date">Soonest first</option><option value="members">Most travelers</option></select><span class="event-chip">${trips.length} open ${trips.length===1?'tour':'tours'}</span></div>${trips.length?`<section class="tour-card-grid">${trips.map((t,i)=>{let owner=getUser(t.ownerId),req=state.requests.find(r=>r.tripId===t.id&&r.userId===state.currentUserId);let art=['','t2','t3','t4'][i%4];return `<article class="tour-card" data-tour-detail="${t.id}"><div class="tour-art ${art}"></div><div class="tour-card-body"><span class="badge badge-green">${dateRange(t)}</span><h3>${escapeHtml(t.title)}</h3><p>⌖ ${escapeHtml(t.destination)}</p><div class="trip-members">${members(t.id).slice(0,3).map(m=>avatar(getUser(m.userId))).join('')}<small>${members(t.id).length} going</small></div><p style="margin-top:9px;line-height:1.6">${escapeHtml(t.description)}</p><div class="tour-meta"><span>${escapeHtml(t.interests||'Open to all interests')}</span><b>${req?.status==='pending'?'Request sent':`${money(t.budgetMinor,t.currency)} budget`}</b></div><div class="tour-meta"><span>Hosted by ${escapeHtml(owner.name.split(' ')[0])}</span><button class="btn ${req?.status==='pending'?'btn-soft':'btn-primary'} btn-sm" data-join="${t.id}" ${req?.status==='pending'?'disabled':''}>${req?.status==='pending'?'Pending':'Ask to join'}</button></div></div></article>`}).join('')}</section>`:`<div class="panel empty-state"><div class="empty-icon">⌕</div><b>No matching tours just yet</b><p>Try a different destination or post your own travel plan.</p><button class="btn btn-primary btn-sm" data-action="new-trip">Post a tour</button></div>`}`;}

  function renderPlaces(){const suggestions=placeMatches.length?`<div class="place-search-results">${placeMatches.map((p,i)=>`<button type="button" class="place-result" data-place-result="${i}"><b>${escapeHtml(p.label)}</b><small>${escapeHtml(p.description||'Location')}</small></button>`).join('')}</div>`:'';const travelOptions=placeRoute?placeTravelOptions():[];
    const selected=placeSelected?`<section class="place-detail-hero panel" style="${placeSelected.image?`--place-hero:url('${escapeHtml(placeSelected.image)}')`:''}"><div class="place-detail-hero-copy"><span class="place-kicker">YOUR DESTINATION GUIDE</span><h2>${escapeHtml(placeSelected.name)}</h2><p>${escapeHtml(placeSelected.description||'Explore this destination, its nearby places, and useful trip details.')}</p><div class="place-detail-actions"><a class="btn btn-light btn-sm" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=${placeSelected.lat}&mlon=${placeSelected.lon}#map=13/${placeSelected.lat}/${placeSelected.lon}">Open destination map ↗</a>${placeSelected.wikipedia?`<a class="place-hero-link" target="_blank" rel="noopener" href="${escapeHtml(placeSelected.wikipedia)}">Source article ↗</a>`:''}<button class="btn btn-primary btn-sm" data-place-plan>Plan a trip here →</button></div></div><span class="place-hero-caption">Images and destination facts update from public travel references</span></section>
      <section class="place-detail-grid"><article class="panel place-description-card"><div class="eyebrow">GET TO KNOW THE PLACE</div><h2>${escapeHtml(placeSelected.name)}</h2><p class="place-long-description">${escapeHtml(placeSummary||placeSelected.description||'Loading the longer destination overview…')}</p><div class="place-source-note">${placeSummary?'Destination overview from Wikipedia.':'Loading expanded reference details…'} ${placeSelected.wikipedia?`<a href="${escapeHtml(placeSelected.wikipedia)}" target="_blank" rel="noopener">View source ↗</a>`:''}</div></article><aside class="panel place-facts-card"><div class="eyebrow">AT A GLANCE</div><div class="place-fact"><span>📍</span><div><b>Location</b><small>${placeSelected.lat!=null&&placeSelected.lon!=null?`${Number(placeSelected.lat).toFixed(4)}, ${Number(placeSelected.lon).toFixed(4)}`:'Coordinates not available'}</small></div></div><div class="place-fact"><span>🛏️</span><div><b>Places to stay nearby</b><small>${placeBusy==='stays'?'Searching nearby…':`${placeStays.length} mapped listings within 5 km`}</small></div></div><div class="place-fact"><span>🖼️</span><div><b>Photo guide</b><small>${placeBusy==='photos'?'Loading photos…':`${placePhotos.length} related images found`}</small></div></div><div class="place-fact"><span>🧭</span><div><b>Travel from you</b><small>${placeRoute?`${placeRoute.km.toFixed(1)} km · ${placeRoute.label}`:'Set your starting location below'}</small></div></div></aside></section>
      <section class="place-metrics"><article class="stat-card"><div class="stat-top">From your location <span class="stat-icon">⌖</span></div><div class="stat-val">${placeRoute?`${placeRoute.km.toFixed(1)} km`:'Not set'}</div><div class="stat-foot">${placeRoute?escapeHtml(placeRoute.label):'Share current location to calculate a route'}</div></article><article class="stat-card"><div class="stat-top">Lowest estimated trip budget <span class="stat-icon">₹</span></div><div class="stat-val">${placeRoute?money(Math.round(7000*Math.max(1,Number(placeTravelers)||1)*3*100),'INR'):'Add your starting location'}</div><div class="stat-foot">${placeRoute?`3 days · ${placeTravelers} traveler${placeTravelers===1?'':'s'} · budget travel estimate`:'Plan from GPS or enter a starting city'}</div></article><article class="stat-card"><div class="stat-top">Nearby places to stay <span class="stat-icon">⌂</span></div><div class="stat-val">${placeStays.length|| (placeBusy==='stays'?'…':'—')}</div><div class="stat-foot">Map listings within about 5 km</div></article></section>
      <section class="panel place-origin-panel"><div><div class="panel-title">Where are you starting?</div><div class="panel-sub">Use your current location or enter a city. Location permission is requested only when you press the button.</div></div><div class="place-origin-controls"><button class="btn btn-sm" data-place-origin>⌖ Use my location</button><label class="place-rate place-origin-city"><span>Starting city</span><span><input id="placeOriginText" type="text" value="${escapeHtml(placeOriginName)}" placeholder="e.g. Bengaluru" aria-label="Starting city"><button type="button" class="place-origin-set" data-place-origin-text>Set</button></span></label><label class="place-rate"><span>Travelers</span><span><input id="placeTravelers" type="number" min="1" max="30" value="${placeTravelers}" aria-label="Number of travelers"></span></label><label class="place-rate"><span>Car cost per km (optional)</span><span><b>₹</b><input id="placeRate" type="number" min="0" step="1" value="${placeRate||''}" placeholder="12" aria-label="Your cost in rupees per kilometer"><small>INR/km</small></span></label></div>${placeOrigin?`<small class="place-origin-status">Starting point set${placeOriginName?` · ${escapeHtml(placeOriginName)}`:''} · ${escapeHtml(placeRoute?.label||'calculating route…')}</small>`:''}</section>
      ${placeRoute?`<section class="place-travel-options"><div class="place-section-heading"><div><div class="eyebrow">COMPARE YOUR JOURNEY</div><h2>Travel options from ${escapeHtml(placeOriginName||'your location')}</h2><p>One-way fare ranges for ${placeTravelers} traveler${placeTravelers===1?'':'s'} · estimates only, not live quotes.</p></div><button class="btn btn-primary btn-sm" data-place-budget-plan="${travelOptions.find(option=>option.recommended)?.mode||'bus'}">✧ Build lowest-cost plan</button></div><div class="place-mode-grid">${travelOptions.map(option=>`<article class="panel place-mode-card ${option.recommended?'recommended':''}"><div class="place-mode-title"><span>${option.icon}</span><div><b>${option.name}</b><small>${option.distanceLabel}</small></div>${option.recommended?'<em>LOWEST ESTIMATE</em>':''}</div><strong>${option.low===null?'Route unavailable':`${money(option.low*100,'INR')} – ${money(option.high*100,'INR')}`}</strong><small class="place-mode-per">${option.perPerson}</small><div class="place-mode-actions"><a target="_blank" rel="noopener noreferrer" href="${option.url}">Check current options ↗</a><button type="button" data-place-budget-plan="${option.mode}">Plan with ${option.name.toLowerCase()}</button></div></article>`).join('')}</div><div class="panel place-smart-tips"><b>Smart trip suggestions</b><ul>${placeTravelTips()}</ul></div></section>`:`<section class="panel place-travel-prompt"><b>See routes, travel options, and a budget plan</b><span>Set a starting point above to compare bus, train, flight, and car estimates for this destination.</span></section>`}
      <div class="place-section-heading"><div><div class="eyebrow">STAY NEARBY</div><h2>Rooms and stays</h2><p>Places listed on OpenStreetMap. Check live room availability and rates with a booking site.</p></div></div>${placeBusy==='stays'?`<div class="panel place-empty">Finding nearby accommodation…</div>`:placeStays.length?`<section class="stay-grid">${placeStays.map(s=>`<article class="panel stay-card"><div class="stay-type">⌂ ${escapeHtml(s.type)}</div><h3>${escapeHtml(s.name)}</h3><p>${s.distance?`${s.distance.toFixed(1)} km from destination centre · `:''}${escapeHtml(s.address||'Address not listed')}</p><div class="stay-rate">Live room rate <b>Not provided by map data</b></div><div class="stay-actions"><a class="btn btn-primary btn-sm" target="_blank" rel="noopener" href="https://www.google.com/travel/search?q=${encodeURIComponent(s.name+' '+placeSelected.name+' hotels')}">Check rooms & price ↗</a><a class="text-link" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=${s.lat}&mlon=${s.lon}#map=17/${s.lat}/${s.lon}">Map</a></div></article>`).join('')}</section>`:`<div class="panel place-empty">${placeError?escapeHtml(placeError):'No mapped stays loaded yet.'}<div class="stay-actions"><a class="text-link" target="_blank" rel="noopener" href="https://www.google.com/maps/search/${encodeURIComponent('hotels in '+placeSelected.name)}">Browse hotels on Google Maps ↗</a><a class="text-link" target="_blank" rel="noopener" href="https://www.google.com/travel/search?q=${encodeURIComponent('hotels in '+placeSelected.name)}">Check current hotel offers ↗</a></div></div>`}
      <div class="place-section-heading"><div><div class="eyebrow">PHOTOS AND HIGHLIGHTS</div><h2>${escapeHtml(placeSelected.name)} in pictures</h2><p>Images from Wikimedia Commons, matched to this location.</p></div></div>${placePhotos.length?`<section class="place-photo-grid">${placePhotos.map(p=>`<a class="place-photo" href="${escapeHtml(p.page)}" target="_blank" rel="noopener"><img src="${escapeHtml(p.thumb)}" alt="${escapeHtml(p.title)}" loading="lazy" decoding="async"><span>${escapeHtml(p.title)}</span></a>`).join('')}</section>`:`<div class="panel place-empty">${placeBusy==='photos'?'Loading related photos…':'No related photos were found for this search.'}</div>`}<p class="place-attribution">Place and lodging data © OpenStreetMap contributors. Destination descriptions and images come from Wikidata/Wikimedia Commons. Verify listing details before booking.</p>`:`<section class="panel place-start"><div class="place-start-icon">⌖</div><h2>Explore a destination</h2><p>Search a city or landmark to see a destination overview, photos, and mapped places to stay.</p><div class="place-search-large"><input id="placeSearch" value="${escapeHtml(placeSearchText)}" placeholder="Try Jaipur, Kyoto, or Eiffel Tower" autocomplete="off"><button class="btn btn-primary" data-place-search ${placeBusy==='search'?'disabled':''}>${placeBusy==='search'?'Searching…':'Search location'}</button></div>${suggestions}${placeError?`<div class="place-error">${escapeHtml(placeError)}</div>`:''}<div class="form-note">Room availability and nightly prices come from booking providers, not map data. This preview opens a partner search for current offers.</div></section>`;
    const searchPanel=`<section class="panel place-search-panel"><div class="place-search-large"><input id="placeSearch" value="${escapeHtml(placeSearchText)}" placeholder="Search city, region, or landmark…" autocomplete="off"><button class="btn btn-primary" data-place-search ${placeBusy==='search'?'disabled':''}>${placeBusy==='search'?'Searching…':'Search location'}</button></div>${suggestions}${placeError?`<div class="place-error">${escapeHtml(placeError)}</div>`:''}</section>`;
    const startPanel=`<section class="panel place-start"><div class="place-start-icon">⌖</div><h2>Explore a destination</h2><p>Search a city or landmark to see an overview, nearby stays, travel distance, and related photos.</p><div class="form-note">Live room availability and nightly prices require a booking provider. This preview links to current partner searches.</div></section>`;
    return `<section class="page-heading"><div><div class="eyebrow">DESTINATION DETAILS</div><h1>Explore a location.</h1><p>Search a place for useful details, nearby stays, photos, and travel distance.</p></div></section>${searchPanel}${placeSelected?selected:startPanel}`;}

  function placeImageFor(name){const q=String(name||'').toLowerCase();if(/\bgoa\b/.test(q))return 'https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=1100&q=78';if(/\bjaipur\b/.test(q))return 'https://images.unsplash.com/photo-1599661046827-dacff0c0f09a?auto=format&fit=crop&w=1100&q=78';if(/\bkerala\b/.test(q))return 'https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=1100&q=78';if(/\bbali\b/.test(q))return 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1100&q=78';return '';}
  function fetchWithTimeout(url,options={},timeoutMs=8000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);return fetch(url,{...options,signal:controller.signal}).finally(()=>clearTimeout(timer));}
  async function searchNominatimPlaces(query){const url=new URL('https://nominatim.openstreetmap.org/search');url.search=new URLSearchParams({q:query,format:'jsonv2',addressdetails:'1',extratags:'1',limit:'8'});const response=await fetchWithTimeout(url,{headers:{'Accept-Language':'en'}},8000);if(!response.ok)throw new Error('OpenStreetMap location search is unavailable.');const rows=await response.json();return rows.map(item=>{const shortName=String(item.name||item.display_name||query),address=item.address||{},locality=address.city||address.town||address.village||address.county||address.state||address.country,article=item.extratags?.wikipedia||'';return {id:`osm-${item.osm_type}-${item.osm_id}`,source:'openstreetmap',label:locality&& !shortName.toLowerCase().includes(locality.toLowerCase())?`${shortName}, ${locality}`:shortName,description:[item.type?.replaceAll('_',' '),locality].filter(Boolean).join(' · ')||'Mapped location',lat:Number(item.lat),lon:Number(item.lon),wikipedia:article.includes(':')?`https://${article.split(':')[0]}.wikipedia.org/wiki/${encodeURIComponent(article.split(':').slice(1).join(':').replaceAll(' ','_'))}`:''};});}
  async function searchPlaces(){const query=placeSearchText.trim();if(query.length<2){placeError='Enter at least 2 characters to search.';render();return;}placeBusy='search';placeError='';placeMatches=[];render();try{const cacheKey=query.toLowerCase();const cached=placeSearchCache.get(cacheKey);if(cached&&Date.now()-cached.time<10*60*1000){placeMatches=cached.rows;return;}const normalized=query.toLowerCase().replace(/,\s*india$/,'').trim();if(['goa','goa india','goa state'].includes(normalized)){placeMatches=[{id:'Q1171',label:'Goa, India',description:'Coastal state in western India, known for its beaches, Portuguese-era architecture, and Konkan culture.'}];placeSearchCache.set(cacheKey,{time:Date.now(),rows:placeMatches});return;}try{const url=new URL('https://www.wikidata.org/w/api.php');url.search=new URLSearchParams({action:'wbsearchentities',search:query,language:'en',uselang:'en',type:'item',limit:'8',format:'json',origin:'*'});const response=await fetch(url);if(response.ok){const data=await response.json();placeMatches=(data.search||[]).filter(x=>!/ontology|protein|annotation|gene/i.test(`${x.label} ${x.description||''}`)).map(x=>({id:x.id,label:x.label,description:x.description||''}));}}catch{}if(!placeMatches.length)placeMatches=await searchNominatimPlaces(query);if(!placeMatches.length)placeError='No matching locations found. Try a nearby city, region, or landmark.';else placeSearchCache.set(cacheKey,{time:Date.now(),rows:placeMatches});}catch(e){placeError=e.message||'Could not search locations. Check your internet connection.';}finally{placeBusy='';render();}}
  async function choosePlace(match){placeSelected={id:match.id,name:match.label,description:match.description,lat:match.lat??null,lon:match.lon??null,wikipedia:match.wikipedia||'',image:placeImageFor(match.label)};placeSummary='';placeMatches=[];placePhotos=[];placeStays=[];placeRoute=null;placeError='';placeBusy='details';render();if(match.source==='openstreetmap'){if(placeSelected.wikipedia)loadPlaceSummary(decodeURIComponent(placeSelected.wikipedia.split('/wiki/')[1]||''),match.id);if(placeSelected.lat!=null&&placeSelected.lon!=null){loadNearbyStays();if(placeOrigin)loadPlaceRoute();}loadPlacePhotos();placeBusy='';render();return;}try{const api=new URL('https://www.wikidata.org/w/api.php');api.search=new URLSearchParams({action:'wbgetentities',ids:match.id,props:'claims|descriptions|sitelinks|labels',languages:'en',format:'json',origin:'*'});const response=await fetch(api);if(!response.ok)throw new Error('Could not load place details.');const data=await response.json(),entity=data.entities?.[match.id]||{},coord=entity.claims?.P625?.[0]?.mainsnak?.datavalue?.value,article=entity.sitelinks?.enwiki?.title;placeSelected={...placeSelected,description:entity.descriptions?.en?.value||match.description||'Explore this destination and nearby travel options.',lat:coord?.latitude??placeSelected.lat,lon:coord?.longitude??placeSelected.lon,wikipedia:article?`https://en.wikipedia.org/wiki/${encodeURIComponent(article.replace(/ /g,'_'))}`:placeSelected.wikipedia};const imageName=entity.claims?.P18?.[0]?.mainsnak?.datavalue?.value;if(imageName)placeSelected.image=`https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(imageName.replace(/ /g,'_'))}?width=1600`;render();if(article)loadPlaceSummary(article,match.id);if(placeSelected.lat!=null&&placeSelected.lon!=null){loadNearbyStays();if(placeOrigin)loadPlaceRoute();}loadPlacePhotos();}catch(e){placeError=e.message||'Could not load this location.';}finally{placeBusy='';render();}}
  async function loadPlaceSummary(article,placeId){try{const slug=article.split('/').map(encodeURIComponent).join('/'),r=await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${slug}`);if(!r.ok)throw new Error('summary');const data=await r.json();if(placeSelected?.id===placeId){placeSummary=data.extract||'';if(!placeSelected.image&&data.thumbnail?.source)placeSelected.image=data.thumbnail.source;render();}}catch{}}
