  function exportCsv(tripId){const trips=tripId?[getTrip(tripId)]:myTrips();const rows=[['Trip','Expense','Date','Category','Paid by','Total','Currency','Split method','Shares']];trips.filter(Boolean).forEach(t=>state.expenses.filter(e=>e.tripId===t.id).forEach(e=>rows.push([t.title,e.description,e.date,e.category,getUser(e.payerId).name,(e.amountMinor/100).toFixed(2),e.currency,e.splitMethod,e.shares.map(s=>`${getUser(s.userId).name}: ${(s.amountMinor/100).toFixed(2)}`).join('; ')])));const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=tripId?`trip-companion-${tripId}-expenses.csv`:'trip-companion-my-expenses.csv';a.click();URL.revokeObjectURL(a.href);toast('Expense summary exported.');}
